const camera={x:0,y:0};
function updateCamera(dt=0,snap=false){const L=levels[index],tx=Math.max(0,Math.min(L.worldWidth-900,p.x+p.w/2-380)),ty=Math.max(-230,Math.min(0,p.y-120)),blend=snap?1:1-Math.exp(-dt*7);camera.x+=(tx-camera.x)*blend;camera.y+=(ty-camera.y)*blend;}
