if(p.riding!==null){const q=tiles[p.riding];if(q.kind==='crumble')return {text:'脚下平台还有 '+Math.max(0,crumbleWindow()-q.trigger).toFixed(1)+' 秒消失，准备跳到下一块。',target:null};if(q.kind==='lift')return {text:q.dy<0?'升降梯正在上升，站稳，靠近高台时再跳。':'升降梯正在下降，可以等下一轮上升。',target:null};if(q.kind==='move')return {text:'平台正在载你移动，靠近对岸后再起跳。',target:null};if(q.kind==='belt')return {text:q.amount>0?'传送带正在推你向右，跳跃前留出刹车距离。':'这段传送带向左，按住向右前进，必要时跳过去。',target:null};}
