function map(){ $('levels').innerHTML='';levels.forEach((l,i)=>{if(i%10===0){let h=document.createElement('div');h.className='chapter';h.textContent=['01–10 · 云端长途赛','11–20 · 秘境寻门','21–30 · 魔王前哨','31–40 · 迷雾远征','41–50 · 星河险路','51–60 · 终极挑战'][i/10];$('levels').appendChild(h);}let b=document.createElement('button');b.className='level'+(i===index?' active':'');b.disabled=i>=saved.unlocked;b.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><span><span class="level-name">${l.name}</span><span class="level-sub">${l.sub} · ${l.requiredStars}★开门</span></span><span class="level-end">${saved.completed[i]?'★ '+saved.best[i]:'→'}</span>`;b.onclick=()=>load(i,true);$('levels').appendChild(b)});$('progress').textContent=saved.completed.filter(Boolean).length+' / '+levels.length+' 完成';}
function makeTiles(){tiles=levels[index].platforms.map(([x,y,w,kind='normal',amount=0,speed=1])=>({x,y,w,kind,amount,speed,baseX:x,baseY:y,active:true,trigger:-1,dx:0,dy:0}));advanceTiles(0);}
function advanceTiles(dt){for(const tile of tiles){const ox=tile.x,oy=tile.y;if(tile.kind==='move')tile.x=tile.baseX+Math.sin(t*tile.speed)*tile.amount;if(tile.kind==='lift')tile.y=tile.baseY-Math.sin(t*tile.speed)*tile.amount;tile.dx=tile.x-ox;tile.dy=tile.y-oy;if(tile.kind==='phase')tile.active=((t+tile.amount)%tile.speed)<tile.speed*.7;if(tile.kind==='crumble'&&tile.trigger>=0){tile.trigger+=dt;tile.active=tile.trigger<crumbleWindow();if(tile.trigger>=crumbleWindow()+3){tile.trigger=-1;tile.active=true;}}}}
function newPlayer(x=45,y=380){return {x,y,w:28,h:35,crouched:false,vx:0,vy:0,jumps:0,ground:false,coyote:0,riding:null,jumpBuffer:0};}
function load(i,play=false){index=i;p=newPlayer(45,levels[i].platforms[0][1]-50);boss=levels[i].boss?{hp:levels[i].bossHP,max:levels[i].bossHP,cooldown:0,clock:0,shots:[],x:levels[i].bossX,y:370,plan:null,lastAttack:null}:null;collectedKey=false;goalRevealed=!levels[i].hiddenGoal;doors=levels[i].doors.map(d=>({...d,revealed:!d.hidden,verified:false}));doorCursor=0;spawnPoint=null;visitedCheckpoints=new Set();doorMessageUntil=0;stars=levels[i].stars.map(([x,y])=>({x,y,got:false}));t=0;particles=[];checkpoint=false;portalCooldown=0;notice='';noticeUntil=0;coach={idle:0,markUntil:0,target:null};makeTiles();resetControls();state=play?'playing':'ready';if(play)c.focus({preventScroll:true});$('overlay').hidden=play;$('levelNo').textContent=String(i+1).padStart(2,'0')+' / '+String(levels.length).padStart(2,'0');$('levelName').textContent=levels[i].name;$('route').textContent=levels[i].route;$('bossbar').hidden=!boss;$('bossname').textContent=levels[i].name;$('checkpoint').textContent=checkpoint?'⚑ 检查点已激活':'⚑ 检查点未激活';$('pause').textContent='Ⅱ';updateCamera(0,true);hud();map();}
function respawn(){if(!checkpoint){load(index,true);return;}const [x,y]=spawnPoint;p=newPlayer(x,y-35);makeTiles();portalCooldown=1;particles=[];if(boss){boss.shots=[];boss.clock=0;boss.cooldown=1;boss.plan=null;}state='playing';resetControls();$('overlay').hidden=true;c.focus({preventScroll:true});updateCamera(0,true);say('从休息点继续！星星、钥匙和验门进度都保留。');hud();}
