function hud(){refreshSmart();const count=stars.filter(s=>s.got).length;$('star-goal').textContent=count>=levels[index].requiredStars?'★ 星星已达标':'★ 开门需要 '+levels[index].requiredStars+' 颗，还差 '+(levels[index].requiredStars-count)+' 颗';$('door-status').textContent='验门 '+doors.filter(d=>d.verified).map((d,i)=>(i+1)+(d.real?'真':'假')).join(' · ')+(doorCursor<doors.length?' → 找 '+(doorCursor+1)+' 号'+(doors[doorCursor].hidden&&!doors[doorCursor].revealed?'（隐藏）':''):' ✓');$('journey').textContent='镜头自动跟随 · 路程 '+Math.min(100,Math.round((p.x+14)/levels[index].goal[0]*100))+'%';$('checkpoint').textContent=checkpoint?'⚑ 休息点已保存':'⚑ 寻找休息点';if(boss){$('bosshealth').textContent=boss.hp>0?'♥'.repeat(boss.hp)+'♡'.repeat(boss.max-boss.hp):'已击败！收星验门后通关';$('bossphase').textContent=boss.hp<=0?'胜利':boss.hp<=2?'第二阶段 · 双弹连发':'第一阶段 · 躲避反击';}$('hint').textContent=t<noticeUntil?notice:smartEnabled?coachAdvice().text:levels[index].hint;$('stars').textContent=stars.filter(s=>s.got).length+' / '+stars.length;let sec=Math.floor(t);$('timer').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function modal(title,text,action,label){$('modalTitle').textContent=title;$('modalText').textContent=text;$('action').textContent=label;$('action').onclick=action;$('extra').hidden=true;$('overlay').hidden=false;resetControls();}
