function update(dt){if(state!=='playing')return;updatePosture();p.jumpBuffer=Math.max(0,p.jumpBuffer-dt);t+=dt;portalCooldown=Math.max(0,portalCooldown-dt);const L=levels[index];advanceTiles(dt);
if(p.riding!==null){const tile=tiles[p.riding];if(tile.active&&p.ground){p.x+=tile.dx;p.y+=tile.dy;}else{p.riding=null;p.ground=false;p.jumps=Math.max(1,p.jumps);}}
const oldX=p.x,oldY=p.y;const belt=p.riding!==null&&tiles[p.riding].kind==='belt'?tiles[p.riding].amount:0;const wind=!p.ground?(L.wind||0):0;p.vx=((keys.right?1:0)-(keys.left?1:0))*(p.crouched?125:235)+belt+wind;p.x=Math.max(0,Math.min(L.worldWidth-p.w,p.x+p.vx*dt));
for(const [x,y] of L.spikes){const bounds=spikeBounds(x,y,p.y,p.y+p.h);if(!bounds)continue;const [left,right]=bounds;if(p.vx>0&&oldX+p.w<=left+.001&&p.x+p.w>left){p.x=left-p.w;p.vx=0;}else if(p.vx<0&&oldX>=right-.001&&p.x<right){p.x=right;p.vx=0;}}
for(const [x,y,w,h]of L.beams||[]){if(p.y+p.h>y&&p.y<y+h){if(oldX+p.w<=x&&p.x+p.w>x){p.x=x-p.w;p.vx=0;}else if(oldX>=x+w&&p.x<x+w){p.x=x+w;p.vx=0;}}}
const bottom=p.y+p.h;p.vy+=1150*dt;p.y+=p.vy*dt;const nextBottom=p.y+p.h,was=p.ground;p.ground=false;p.riding=null;
// Pick the first crossed surface, independent of route/platform declaration order.
let landing=-1,top=Infinity;for(let i=0;i<tiles.length;i++){const q=tiles[i];if(q.active&&p.vy>=0&&bottom<=q.y+1&&p.y+p.h>=q.y&&p.x+p.w>q.x+2&&p.x<q.x+q.w-2&&q.y<top){landing=i;top=q.y;}}
if(landing>=0){const q=tiles[landing];p.y=q.y-p.h;p.vy=0;p.ground=true;p.jumps=0;p.riding=landing;if(q.kind==='crumble'&&q.trigger<0)q.trigger=0;}
for(const [x,y,w,h]of L.beams||[]){if(p.x+p.w>x&&p.x<x+w){if(p.vy<0&&oldY>=y+h&&p.y<y+h){p.y=y+h;p.vy=0;}else if(p.vy>=0&&bottom<=y&&p.y+p.h>=y){p.y=y-p.h;p.vy=0;p.ground=true;p.jumps=0;}}}
if(!p.ground){if(was)p.coyote=assisted()?.17:.09;p.coyote-=dt;if(p.coyote<=0&&p.jumps===0)p.jumps=1;}
for(const [x,y]of L.spikes){const tipX=x+14,tipY=y-25;if(nextBottom>bottom&&bottom<=tipY&&p.y+p.h>=tipY&&p.x<tipX&&p.x+p.w>tipX){fail('spike');return;}if(oldY>=y&&p.y<y&&p.x+p.w>x&&p.x<x+28){p.y=y;p.vy=0;continue;}const bounds=spikeBounds(x,y,p.y,p.y+p.h);if(bounds&&p.x+p.w>bounds[0]&&p.x<bounds[1]){p.x=p.x+p.w/2<tipX?bounds[0]-p.w:bounds[1];p.vx=0;}}
// Spring pads may sit on a larger normal platform; detect them separately.
if(p.ground){for(const q of tiles)if(q.kind==='spring'&&Math.abs(p.y+p.h-q.y)<1&&p.x+p.w>q.x+3&&p.x<q.x+q.w-3){p.vy=-690;p.jumps=0;p.ground=false;p.riding=null;burst(p.x+14,q.y,'#f0a0c6');tone(540,.18);break;}}
for(const h of hammerPositions())if(circleHitsPlayer(h.x,h.y,18)){fail('hammer');return;}
if(p.y>560){fail();return;}
for(const [x,y,tx,ty] of L.portals||[])if(portalCooldown===0&&Math.abs(p.x+14-x)<23&&Math.abs(p.y+p.h-y)<45){p.x=tx-14;p.y=ty-p.h;p.vx=p.vy=0;p.jumps=0;p.ground=false;p.riding=null;portalCooldown=1.2;burst(tx,ty-25,'#b8a0e7');say('传送成功！也可以重玩试试另一条路线。');tone(780,.16);updateCamera(0,true);break;}
for(const [i,[cx,cy]]of L.checkpoints.entries())if(!visitedCheckpoints.has(i)&&p.ground&&Math.abs(p.x+14-cx)<35&&Math.abs(p.y+p.h-cy)<2){visitedCheckpoints.add(i);saveCheckpoint(cx,cy);say('休息点已保存！星星和验门进度会保留。');tone(650,.15);}
if(L.key&&!collectedKey&&Math.hypot(p.x+14-L.key[0],p.y+p.h/2-L.key[1])<28){collectedKey=true;say('钥匙拿到了！继续收星，按顺序验门。');$('route').textContent=L.route+' ✓';tone(820,.2);}
updateBoss(dt,bottom);if(state!=='playing')return;
for(const s of stars)if(!s.got&&Math.hypot(p.x+14-s.x,p.y+p.h/2-s.y)<30){s.got=true;burst(s.x,s.y,'#e3b64f');tone(720,.14);}
updateDoors();if(state!=='playing')return;
if(p.ground&&p.jumpBuffer>0)jump();
if((keys.left||keys.right)&&Math.hypot(p.x-oldX,p.y-oldY)<.3)coach.idle+=dt;else coach.idle=Math.max(0,coach.idle-dt*2);if(smartEnabled&&coach.idle>3&&t>=coach.markUntil){requestHint();coach.idle=0;}
particles.forEach(a=>{a.x+=a.vx*dt;a.y+=a.vy*dt;a.life-=dt});particles=particles.filter(a=>a.life>0);hud();}
