function loop(ms){let dt=Math.min((ms-last)/1000,.05);last=ms;acc+=dt;while(acc>=1/120){update(1/120);acc-=1/120;}updateCamera(dt);draw(ms/1000);requestAnimationFrame(loop)}
document.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','KeyS','Space','KeyA','KeyD','KeyW','KeyR','KeyP','Escape'].includes(e.code)){if(e.target.tagName==='BUTTON'&&e.code==='Space')return;e.preventDefault();if(['ArrowDown','KeyS'].includes(e.code))setCrouchInput(e.code,true);if(e.code==='ArrowLeft'||e.code==='KeyA')keys.left=true;if(e.code==='ArrowRight'||e.code==='KeyD')keys.right=true;if(!e.repeat){if(['Space','ArrowUp','KeyW'].includes(e.code))jump();if(e.code==='KeyR')load(index,true);if(e.code==='KeyP'||e.code==='Escape')pause();}}});document.addEventListener('keyup',e=>{if(['ArrowDown','KeyS'].includes(e.code))setCrouchInput(e.code,false);if(['ArrowLeft','KeyA'].includes(e.code))keys.left=false;if(['ArrowRight','KeyD'].includes(e.code))keys.right=false;});window.addEventListener('blur',()=>{resetControls();if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){resetControls();if(state==='playing')pause()}});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(b.dataset.key==='jump')jump();else if(b.dataset.key==='crouch')setCrouchInput('pointer-'+e.pointerId,true);else keys[b.dataset.key]=true;});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,e=>{if(b.dataset.key==='crouch')setCrouchInput('pointer-'+e.pointerId,false);else if(b.dataset.key!=='jump')keys[b.dataset.key]=false})});$('smart-toggle').onclick=toggleSmart;$('hint-button').onclick=()=>{requestHint();hud();c.focus({preventScroll:true})};$('pause').onclick=pause;$('restart').onclick=()=>load(index,true);$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'♪ ×':'♪';$('sound').setAttribute('aria-label',muted?'开启音效':'关闭音效');tone(600)};$('action').onclick=()=>{load(index,true);$('action').blur()};load(0);requestAnimationFrame(loop);
